def transform_with_min_plus_one(grid):
    if not grid:
        return []
    nrows = len(grid)
    ncols = len(grid[0])
    unique_vals = set(val for row in grid for val in row)
    min_val = min(unique_vals)

    zero_rows = {r for r in range(nrows) if all(grid[r][c] == min_val for c in range(ncols))}
    zero_cols = {c for c in range(ncols) if all(grid[r][c] == min_val for r in range(nrows))}

    result = []
    for r in range(nrows):
        row = []
        for c in range(ncols):
            if r in zero_rows or c in zero_cols:
                row.append(min_val + 1)
            else:
                row.append(grid[r][c])
        result.append(row)
    return result

